package edu.sc.servicedemo; import jakarta.persistence.*; import java.time.*; @Entity @Table(name="users") class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; String username,password; } @Entity @Table(name="requests") class ServiceRequest { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; String title,details,status="OPEN"; LocalDate scheduledFor; @ManyToOne User user; } interface UserRepo extends org.springframework.data.jpa.repository.JpaRepository<User,Long>{java.util.Optional<User> findByUsername(String u);} interface RequestRepo extends org.springframework.data.jpa.repository.JpaRepository<ServiceRequest,Long>{java.util.List<ServiceRequest> findByStatus(String s);}
